import { describe, expect, it } from "vitest";
import golden from "./fixtures/monitoring-node/projection-golden.json";
import { projectDocument } from "../lib/monitoring/document-projection";
import { sha256, validateProjection, type Observation, type Source } from "../lib/monitoring/source-contract";

// These fixtures were generated by direct calls to the offline Python projector. No collector ran.
const source: Pick<Source, "url" | "relationships"> = golden.source;
const base = golden.cases[0];
function observation(body: Buffer, values: Partial<Observation> = {}): Observation {
  return { ...base.observation, state: "reachable", evidenceType: "observed_http", contentHash: sha256(body), receivedBytes: body.length, ...values };
}
function project(text: string, headers: Record<string, string> = { "content-type": "text/html; charset=utf-8" }) {
  const body = Buffer.from(text); return projectDocument(body, headers, source, observation(body));
}

describe("pure bounded static-document-v1 projector", () => {
  for (const fixture of golden.cases) {
    it(`matches fictional Python projection: ${fixture.name}`, () => {
      const body = Buffer.from(fixture.body);
      const obs = observation(body, fixture.observation as Observation);
      const result = projectDocument(body, fixture.headers, source, obs);
      expect(result).toEqual(fixture.expected);
      validateProjection(result, obs, source);
    });
  }

  it("normalizes attribute order and equivalent entities while retaining meaningful byte differences", () => {
    const result = project(base.body);
    expect(project(golden.cases.find(item => item.name === "syntax-noise")!.body).projectionHash).toBe(result.projectionHash);
    for (const name of ["number", "version", "link", "pre-space", "timestamp"]) {
      expect(project(golden.cases.find(item => item.name === name)!.body).projectionHash).not.toBe(result.projectionHash);
    }
  });

  it("rejects malformed or unsupported markup without repairing a document", () => {
    for (const text of ["<p>x", "<p>x</div>", "<p>x</p><", "<p a='x>x</p>", "<p a= >x</p>", "<p a=1 A=2>x</p>", "<!-- unfinished", "<?xml version='1.0'?>", "<![CDATA[text]]>", "<p>text</p><!unknown>", "<script>unterminated", "<img></img>", "first &unfinished"]) {
      expect(project(text)).toMatchObject({ state: "unsupported", reason: "malformed_markup", sections: [], projectionHash: null });
    }
    // Python removes these exceptional numeric references; this implementation rejects that subset.
    for (const text of ["<p>&#1;</p>", "<p>&#xFFFF;</p>"]) expect(project(text).state).toBe("unsupported");
  });

  it("bounds sections, tokens, nesting, attributes, names and decoded values before retaining content", () => {
    const cases = [
      "<h1>x</h1>".repeat(16), "<p>x</p>".repeat(6667), "<div>".repeat(129),
      `<p ${Array.from({ length: 65 }, (_, index) => `a${index}=x`).join(" ")}>x</p>`,
      `<p ${"a".repeat(257)}=x>x</p>`, `<p a="${"x".repeat(8193)}">x</p>`,
    ];
    for (const text of cases) expect(project(text)).toMatchObject({ state: "incomplete", reason: "projection_limit", sections: [], projectionHash: null });
    expect(project(`<p a="${"&#x1f642;".repeat(8192)}">x</p>`).state).toBe("captured");
    expect(project("<div>".repeat(128) + "x" + "</div>".repeat(128)).state).toBe("captured");
  });

  it("bounds stored previews to 24 words and 160 Unicode characters without rewriting whitespace", () => {
    const result = project(`<h1>${"heading ".repeat(12)}</h1><pre>  ${"word\u0085".repeat(30)}</pre><h2>another</h2><p>tail</p>`);
    expect(result.state).toBe("captured");
    const fragments = result.sections.flatMap(section => [section.heading, section.excerpt]);
    expect(fragments.reduce((total, value) => total + (value.match(/[^\s\u0085]+/gu) ?? []).length, 0)).toBeLessThanOrEqual(24);
    expect(fragments.every(value => [...value].length <= 160)).toBe(true);
    expect(result.sections[1].excerpt).toMatch(/^  word\u0085word/);
    const long = project(`<p>${"🙂".repeat(170)}</p>`);
    expect([...long.sections[0].excerpt]).toHaveLength(160);
    expect(long.sections[0].excerptTruncated).toBe(true);
  });

  it("keeps capture failures explicit for media, charset, encoding, UTF-8 and unsafe text", () => {
    const body = Buffer.from(base.body), obs = observation(body);
    for (const [headers, reason] of [
      [{ "content-type": "application/json" }, "unsupported_media_type"],
      [{ "content-type": "text/html; charset=latin-1" }, "unsupported_charset"],
      [{ "content-type": "text/html;" }, "unsupported_charset"],
      [{ "content-type": "\ufefftext/html" }, "unsupported_media_type"],
      [{ "content-type": "text/html", "content-encoding": "gzip" }, "unsupported_encoding"],
    ] as const) expect(projectDocument(body, headers, source, obs)).toMatchObject({ state: "unsupported", reason, sections: [] });
    const invalid = Buffer.from([0xff]);
    expect(projectDocument(invalid, { "content-type": "text/html" }, source, observation(invalid)).reason).toBe("invalid_utf8");
    for (const text of ["<p>\u0000</p>", "<p>\u202e</p>", "<script>\u0001</script>"]) expect(project(text).reason).toBe("unsafe_text");
  });

  it("preserves incomplete-body outcomes without parsing partial, oversized or unavailable content", () => {
    for (const body of [Buffer.from("<p>partial"), Buffer.alloc(1024 * 1024 + 1, 120)]) {
      const obs = observation(body, { state: "unknown", reason: "partial_or_oversized_body", httpStatus: 206, contentHash: null, bodyComplete: false });
      expect(projectDocument(body, { "content-type": "text/html" }, source, obs)).toMatchObject({ state: "incomplete", reason: "body_unavailable", bodyObservedAt: null, sections: [] });
    }
  });

  it("retains original validated projection and capture date for 304 without mutating prior evidence", () => {
    const body = Buffer.from(base.body), before = observation(body);
    before.documentProjection = projectDocument(body, base.headers, source, before);
    const original = structuredClone(before);
    const after = { ...before, checkedAt: "2026-11-13T00:00:01Z", httpStatus: 304, reason: "not_modified", receivedBytes: 0 };
    const result = projectDocument(Buffer.alloc(0), {}, source, after, before);
    expect(result).toEqual(before.documentProjection);
    expect(result.bodyObservedAt).toBe(before.checkedAt);
    expect(result).not.toBe(before.documentProjection);
    expect(before).toEqual(original);
    const bad = structuredClone(before); bad.documentProjection!.sourceIdentity = "0".repeat(64);
    expect(() => projectDocument(Buffer.alloc(0), {}, source, after, bad)).toThrow(/binding/);
    expect(() => projectDocument(Buffer.alloc(0), {}, source, { ...after, contentHash: "0".repeat(64) }, before)).toThrow(/lineage/);
    expect(projectDocument(Buffer.alloc(0), {}, source, { ...after, state: "unknown", reason: "scanner_policy_refusal", bodyComplete: false, contentHash: null }, before)).toMatchObject({ state: "incomplete", reason: "body_unavailable", bodyObservedAt: null, sections: [] });
    expect(projectDocument(Buffer.alloc(0), {}, source, after)).toMatchObject({ state: "not_captured", reason: "legacy_body_not_retained", bodyObservedAt: null });
  });
});
